{"hypotheses": [
  {
    "name": "Capital Structure Contrarian",
    "mechanism": "Combining high net equity financing (NetEquityFinance) and low net debt financing (NetDebtFinance), offset by low book leverage (BookLeverage), targets firms aggressively issuing equity while reducing debt and leverage. Such firms may be overconfident or overvalued, and the blend captures mispricing from capital structure shifts that is not fully captured by single predictors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetEquityFinance"},
        {"weight": 1.0, "primitive": "NetDebtFinance"},
        {"weight": -1.0, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "NetEquityFinance", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Defensive Analyst Revision Quality",
    "mechanism": "By combining upward analyst EPS forecast revisions (AnalystRevision) and earnings consistency (EarningsConsistency) but subtracting high analyst optimism (AOP), the factor isolates stocks with improving fundamentals untainted by analyst over-exuberance. This attempts to capture true improvements rather than those hyped by sentiment.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "EarningsConsistency"},
        {"weight": -1.0, "primitive": "AOP"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Inventory Cycle Alpha",
    "mechanism": "A blend of low inventory growth (InvGrowth), high asset turnover change (ChAssetTurnover), and high sales growth over inventory growth (GrSaleToGrInv) captures firms efficiently using working capital in expansionary phases, exploiting cyclical mispricings in operational execution that are overlooked by single factors.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "InvGrowth"},
        {"weight": 1.0, "primitive": "ChAssetTurnover"},
        {"weight": 1.0, "primitive": "GrSaleToGrInv"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Deep Value with Governance",
    "mechanism": "Combining high book-to-market (BM), high governance scores (Governance), and low composite equity issuance (CompEquIss), this composite seeks undervalued firms with strong governance and capital discipline, which should be less prone to value traps than simple value screens.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": -1.0, "primitive": "CompEquIss"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Profitability-Adjusted Intangible Growth",
    "mechanism": "Positive returns are expected from blending high R&D-to-market (RD), high operating profitability (OperProf), and growth in intangible capital (IntanBM). This captures profitable innovation that is likely to persist, filtering out low-quality R&D spending.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "IntanBM"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Liquidity Timed Momentum",
    "mechanism": "Combining high residual momentum (ResidualMomentum), high trading volume (DolVol), and low bid-ask spread (BidAskSpread) in falling market volatility regimes captures momentum trades when liquidity is plentiful and transaction costs are low, enhancing realized alpha versus generic momentum.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ResidualMomentum"},
        {"weight": 0.5, "primitive": "DolVol"},
        {"weight": -1.0, "primitive": "BidAskSpread"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "ResidualMomentum", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.72,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Franchise Quality Defensive",
    "mechanism": "This composite favors firms with high gross profits to assets (GP), high brand capital investment (BrandInvest), and high order backlog (OrderBacklog), indicating robust franchises. By combining these, it identifies firms with persistent competitive advantages, especially defensive in weak markets.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 0.5, "primitive": "OrderBacklog"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Short-Term Earnings Accrual Trap",
    "mechanism": "By going short high abnormal accruals (AbnormalAccruals) and total accruals (TotalAccruals), while going long on positive earnings surprises (EarningsSurprise) and high earnings forecast dispersion (ForecastDispersion), this composite bets against firms with suspect accounting signals even if reported earnings are positive, capturing future reversals from mispriced earnings quality.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AbnormalAccruals"},
        {"weight": -1.0, "primitive": "TotalAccruals"},
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AbnormalAccruals", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 18
  }
]}
